    const words = line.split(/\s+/)
    const directive = words[0]

    if (directive === 'task') {
      if (words.length !== 3) {
        throw new CliError(`line ${lineNo}: expected task <name> <cost>`)
      }
      const name = words[1]
      const costStr = words[2]
      if (!NAME_RE.test(name)) {
        throw new CliError(`line ${lineNo}: invalid task name ${name}`)
      }
      if (!COST_RE.test(costStr)) {
        throw new CliError(`line ${lineNo}: cost must be a non-negative integer`)
      }
      if (tasks.has(name)) {
        throw new CliError(`line ${lineNo}: task ${name} is declared twice`)
      }
      tasks.set(name, parseInt(costStr, 10))
    } else if (directive === 'dep') {
      if (words.length < 3) {
        throw new CliError(`line ${lineNo}: expected dep <name> <dependency>...`)
      }
      const owner = words[1]
      const deps = words.slice(2)
      depEntries.push({ owner, deps })
    } else {
      throw new CliError(`line ${lineNo}: unknown directive ${directive}`)
    }
  })

  for (const { owner, deps } of depEntries) {
    if (!tasks.has(owner)) throw new CliError(`unknown task ${owner}`)
    for (const d of deps) {
      if (!tasks.has(d)) throw new CliError(`unknown task ${d}`)
    }
  }

  const edges = new Map()
  for (const name of tasks.keys()) edges.set(name, new Set())
  for (const { owner, deps } of depEntries) {
    const set = edges.get(owner)
    for (const d of deps) set.add(d)
  }

  return { tasks, edges }
}
"}

{"file_path":"src/cycle.js","content":"/**
 * Depth-first search for a cycle, starting from each task in ascending name
 * order and walking each task's dependencies in ascending name order.
 * Returns an array of names (the cycle, first name repeated at the end) or
 * null when the graph is acyclic.
 */
export function findCycle(tasks, edges) {
  const names = [...tasks.keys()].sort()
  const state = new Map() // undefined = unvisited, 1 = on stack, 2 = done
  const stack = []

  function dfs(name) {
    state.set(name, 1)
    stack.push(name)
    const depNames = [...edges.get(name)].sort()
    for (const d of depNames) {
      const s = state.get(d)
      if (s === 1) {
        const idx = stack.indexOf(d)
        const cycle = stack.slice(idx)
        cycle.push(d)
        return cycle
      }
      if (s !== 2) {
        const found = dfs(d)
        if (found) return found
      }
    }
    stack.pop()
    state.set(name, 2)
    return null
  }

  for (const name of names) {
    if (!state.has(name)) {
      const found = dfs(name)
      if (found) return found
    }
  }
  return null
}
"}

{"file_path":"src/times.js","content":"/**
 * Compute { start, finish, depth } for every task, assuming edges form a DAG
 * (call findCycle first). depth is the wave index: 0 for a task with no
 * deps, otherwise one more than the greatest depth among its deps. start is
 * the greatest finish among its deps (0 when it has none); finish is
 * start + cost.
 */
export function computeTimes(tasks, edges) {
  const depthMemo = new Map()
  const finishMemo = new Map()

  function depthOf(name) {
    if (depthMemo.has(name)) return depthMemo.get(name)
    let d = 0
    for (const dep of edges.get(name)) d = Math.max(d, depthOf(dep) + 1)
    depthMemo.set(name, d)
    return d
  }

  function finishOf(name) {
    if (finishMemo.has(name)) return finishMemo.get(name)
    let start = 0
    for (const dep of edges.get(name)) start = Math.max(start, finishOf(dep))
    const f = start + tasks.get(name)
    finishMemo.set(name, f)
    return f
  }

  const result = new Map()
  for (const name of tasks.keys()) {
    const f = finishOf(name)
    const d = depthOf(name)
    result.set(name, { start: f - tasks.get(name), finish: f, depth: d })
  }
  return result
}
"}

{"file_path":"src/pack.js","content":"/**
 * Simulate the build graph on a fixed number of workers, using the priority
 * list-scheduling rule described in the spec.
 */
export function computePriority(tasks, edges) {
  const dependents = new Map()
  for (const name of tasks.keys()) dependents.set(name, [])
  for (const [name, deps] of edges) {
    for (const d of deps) dependents.get(d).push(name)
  }

  const memo = new Map()
  function priorityOf(name) {
    if (memo.has(name)) return memo.get(name)
    let best = 0
    for (const dep of dependents.get(name)) best = Math.max(best, priorityOf(dep))
    const p = tasks.get(name) + best
    memo.set(name, p)
    return p
  }

  const result = new Map()
  for (const name of tasks.keys()) result.set(name, priorityOf(name))
  return result
}

export function pack(tasks, edges, workerCount) {
  const priority = computePriority(tasks, edges)
  const names = [...tasks.keys()]
  const finished = new Map()
  const started = new Set()
  const workers = Array.from({ length: workerCount }, () => ({ freeAt: 0, log: [] }))

  function readyAt(t) {
    const ready = []
    for (const name of names) {
      if (started.has(name)) continue
      let ok = true
      for (const d of edges.get(name)) {
        const f = finished.get(d)
        if (f === undefined || f > t) {
          ok = false
          break
        }
      }
      if (ok) ready.push(name)
    }
    return ready
  }

  let t = 0
  let scheduled = 0
  while (scheduled < names.length) {
    for (;;) {
      const ready = readyAt(t)
      if (ready.length === 0) break
      let widx = -1
      for (let i = 0; i < workers.length; i++) {
        if (workers[i].freeAt <= t) {
          widx = i
          break
        }
      }
      if (widx === -1) break

      ready.sort((a, b) => priority.get(b) - priority.get(a) || (a < b ? -1 : a > b ? 1 : 0))
      const chosen = ready[0]
      const cost = tasks.get(chosen)
      const finish = t + cost
      workers[widx].log.push({ name: chosen, start: t, finish })
      workers[widx].freeAt = finish
      started.add(chosen)
      finished.set(chosen, finish)
      scheduled++
    }
    if (scheduled < names.length) {
      let next = Infinity
      for (const w of workers) if (w.freeAt > t) next = Math.min(next, w.freeAt)
      if (next === Infinity) break
      t = next
    }
  }

  return workers
}
"}

