  let total = 0
  for (const { finish } of times.values()) total = Math.max(total, finish)
  lines.push(`total ${total}`)
  return lines.join('\n') + (lines.length ? '\n' : '')
}

function formatExplain(tasks, times) {
  const names = [...tasks.keys()].sort()
  const lines = names.map((n) => {
    const { start, finish, depth } = times.get(n)
    return `${n} start=${start} finish=${finish} depth=${depth}`
  })
  let total = 0
  for (const { finish } of times.values()) total = Math.max(total, finish)
  lines.push(`total ${total}`)
  return lines.join('\n') + '\n'
}

function formatPack(workers) {
  const lines = workers.map((w, i) => {
    const parts = w.log.map((t) => `${t.name}@${t.start}-${t.finish}`)
    return `worker ${i}:${parts.length ? ' ' + parts.join(' ') : ''}`
  })
  let makespan = 0
  for (const w of workers) for (const t of w.log) makespan = Math.max(makespan, t.finish)
  lines.push(`makespan ${makespan}`)
  return lines.join('\n') + '\n'
}

async function main() {
  const argv = process.argv.slice(2)
  const args = parseArgs(argv)

  const input = await readStdin()
  const { tasks, edges } = parseGraph(input)

  const cycle = findCycle(tasks, edges)
  if (cycle) {
    const err = new Error(`error: cycle: ${cycle.join(' -> ')}`)
    err.cycle = true
    throw err
  }

  let output
  if (args.mode === 'waves') {
    const times = computeTimes(tasks, edges)
    output = formatWaves(tasks, times)
  } else if (args.mode === 'explain') {
    const times = computeTimes(tasks, edges)
    output = formatExplain(tasks, times)
  } else {
    const workers = pack(tasks, edges, args.workers)
    output = formatPack(workers)
  }

  process.stdout.write(output, () => process.exit(0))
}

main().catch((err) => {
  if (err instanceof CliError) {
    process.stderr.write(`error: ${err.message}\n`, () => process.exit(err.code))
    return
  }
  if (err && err.cycle) {
    process.stderr.write(`${err.message}\n`, () => process.exit(3))
    return
  }
  process.stderr.write(`error: ${err && err.message ? err.message : String(err)}\n`, () => process.exit(2))
})
